import { useState } from 'react';
import { JxButton } from '@jinx-ui/react';

interface ContactInfo {
  fullName: string;
  email: string;
  phone: string;
}

interface AddressInfo {
  street: string;
  city: string;
  postalCode: string;
  country: string;
}

interface RegistrationData {
  contact: ContactInfo;
  address: AddressInfo;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [contact, setContact] = useState<ContactInfo>({ fullName: '', email: '', phone: '' });
  const [address, setAddress] = useState<AddressInfo>({ street: '', city: '', postalCode: '', country: '' });

  const isLastStep = step === STEPS.length - 1;

  const canGoNext =
    step === 0
      ? contact.fullName.trim() !== '' && contact.email.trim() !== ''
      : step === 1
        ? address.street.trim() !== '' && address.city.trim() !== ''
        : true;

  const handleNext = () => {
    if (!isLastStep && canGoNext) {
      setStep((s) => s + 1);
    }
  };

  const handleBack = () => {
    setStep((s) => Math.max(0, s - 1));
  };

  const handleSubmit = () => {
    onSubmit({ contact, address });
  };

  return (
    <div
      className="jx-card"
      style={{
        maxWidth: 480,
        padding: 'var(--jx-space-6)',
        borderRadius: 'var(--jx-radius-lg)',
        background: 'var(--jx-color-surface)',
        border: '1px solid var(--jx-color-border)',
      }}
    >
      <ol
        role="list"
        style={{
          display: 'flex',
          gap: 'var(--jx-space-3)',
          listStyle: 'none',
          padding: 0,
          margin: '0 0 var(--jx-space-6) 0',
        }}
      >
        {STEPS.map((label, index) => {
          const isActive = index === step;
          const isDone = index < step;
          return (
            <li
              key={label}
              aria-current={isActive ? 'step' : undefined}
              style={{
                flex: 1,
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                gap: 'var(--jx-space-2)',
              }}
            >
              <span
                style={{
                  width: 28,
                  height: 28,
                  borderRadius: 'var(--jx-radius-full)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: 'var(--jx-font-size-sm)',
                  fontWeight: 'var(--jx-font-weight-medium)',
                  color: isActive || isDone ? 'var(--jx-color-primary-foreground)' : 'var(--jx-color-foreground-muted)',
                  background: isActive || isDone ? 'var(--jx-color-primary)' : 'var(--jx-color-surface-muted)',
                  border: '1px solid var(--jx-color-border)',
                }}
              >
                {index + 1}
              </span>
              <span
                style={{
                  fontSize: 'var(--jx-font-size-sm)',
                  color: isActive ? 'var(--jx-color-foreground)' : 'var(--jx-color-foreground-muted)',
                }}
              >
                {label}
              </span>
            </li>
          );
        })}
      </ol>

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Полное имя</span>
            <input
              className="jx-input"
              value={contact.fullName}
              onChange={(e) => setContact((c) => ({ ...c, fullName: e.target.value }))}
              placeholder="Иван Иванов"
            />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Email</span>
            <input
              className="jx-input"
              type="email"
              value={contact.email}
              onChange={(e) => setContact((c) => ({ ...c, email: e.target.value }))}
              placeholder="ivan@example.com"
            />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Телефон</span>
            <input
              className="jx-input"
              type="tel"
              value={contact.phone}
              onChange={(e) => setContact((c) => ({ ...c, phone: e.target.value }))}
              placeholder="+48 000 000 000"
            />
          </label>
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Улица и дом</span>
            <input
              className="jx-input"
              value={address.street}
              onChange={(e) => setAddress((a) => ({ ...a, street: e.target.value }))}
              placeholder="ул. Примерная, 12"
            />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Город</span>
            <input
              className="jx-input"
              value={address.city}
              onChange={(e) => setAddress((a) => ({ ...a, city: e.target.value }))}
              placeholder="Варшава"
            />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Почтовый индекс</span>
            <input
              className="jx-input"
              value={address.postalCode}
              onChange={(e) => setAddress((a) => ({ ...a, postalCode: e.target.value }))}
              placeholder="00-001"
            />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Страна</span>
            <input
              className="jx-input"
              value={address.country}
              onChange={(e) => setAddress((a) => ({ ...a, country: e.target.value }))}
              placeholder="Польша"
            />
          </label>
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-5)' }}>
          <section style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
            <h3 style={{ margin: 0, fontSize: 'var(--jx-font-size-md)', color: 'var(--jx-color-foreground)' }}>
              Контакты
            </h3>
            <p style={{ margin: 0, color: 'var(--jx-color-foreground-muted)' }}>{contact.fullName || '—'}</p>
            <p style={{ margin: 0, color: 'var(--jx-color-foreground-muted)' }}>{contact.email || '—'}</p>
            <p style={{ margin: 0, color: 'var(--jx-color-foreground-muted)' }}>{contact.phone || '—'}</p>
          </section>
          <section style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
            <h3 style={{ margin: 0, fontSize: 'var(--jx-font-size-md)', color: 'var(--jx-color-foreground)' }}>
              Адрес
            </h3>
            <p style={{ margin: 0, color: 'var(--jx-color-foreground-muted)' }}>{address.street || '—'}</p>
            <p style={{ margin: 0, color: 'var(--jx-color-foreground-muted)' }}>
              {[address.postalCode, address.city].filter(Boolean).join(' ') || '—'}
            </p>
            <p style={{ margin: 0, color: 'var(--jx-color-foreground-muted)' }}>{address.country || '—'}</p>
          </section>
        </div>
      )}

      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          marginTop: 'var(--jx-space-6)',
          gap: 'var(--jx-space-3)',
        }}
      >
        <JxButton variant="secondary" onClick={handleBack} disabled={step === 0}>
          Назад
        </JxButton>
        {isLastStep ? (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleNext} disabled={!canGoNext}>
            Дальше
          </JxButton>
        )}
      </div>
    </div>
  );
}

